mapper.update:
update attach_file af set ord_no = changes.ord_no, modify_user_id = #{userId}, modify_datetime = now() from (values
(cast(#{item.sysId} as varchar), cast(#{item.ordNo} as integer))
) as changes(sys_id, ord_no) where af.sys_id = changes.sys_id and

update attach_file af set delete_yn = 'Y', modify_user_id = #{userId}, modify_datetime = now() where af.sys_id in
#{id}
and

mapper.select:
select sys_id , link_sys_id , original_file_nm , convert_file_nm , file_ext , mime_type , file_size , file_path , pdf_yn , ord_no from attach_file af where af.sys_id in
#{id}
and order by af.sys_id for update
